import time
import os
from picamera2 import Picamera2

# Define the output file for the captured image
OUTPUT_FILE = "image.jpg"

def initialize_camera():
    """Initialize the Raspberry Pi camera module."""
    try:
        camera = Picamera2()
        camera.configure(camera.create_still_configuration())
        camera.start()
        return camera
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None

def capture_image(camera, filename):
    """Capture an image and save it to the specified file."""
    try:
        camera.capture_file(filename)
        print(f"Image saved to {filename}")
    except Exception as e:
        print(f"Error capturing image: {e}")

def main():
    """Main function to capture images repeatedly."""
    camera = initialize_camera()

    if camera is None:
        print("Camera initialization failed. Exiting.")
        return

    try:
        while True:
            capture_image(camera, OUTPUT_FILE)
            time.sleep(0.02)  # Short delay between captures
    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        if camera:
            camera.stop()
            camera.close()
            print("Camera resources released.")

if __name__ == "__main__":
    main()

