import time
import os
from picamera2 import Picamera2

# Define the output file for the captured image
IMAGE_FILE = "image.jpg"

def setup_camera():
    """Initialize the Raspberry Pi camera module."""
    try:
        camera = Picamera2()
        camera.configure(camera.create_still_configuration())
        camera.start()
        return camera
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None

def capture_image(camera):
    """Capture an image and save it to the specified file."""
    try:
        camera.capture_file(IMAGE_FILE)
        print(f"Image captured and saved to {IMAGE_FILE}")
    except Exception as e:
        print(f"Error capturing image: {e}")

def main_loop(camera):
    """Main loop to continuously capture images."""
    try:
        while True:
            capture_image(camera)
            time.sleep(0.15)  # Adjust delay as needed
    except KeyboardInterrupt:
        print("\nExiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        if camera:
            camera.close()
            print("Camera resources released.")

if __name__ == "__main__":
    # Check if the script is running on a Raspberry Pi
    if os.uname()[4][:3] == 'ras':
        camera = setup_camera()
        if camera:
            main_loop(camera)
        else:
            print("Camera setup failed. Exiting.")
    else:
        print("This script must be run on a Raspberry Pi with the camera module connected.")
